{
  "name": "BioShake 加热振荡器",
  "name_en": "BioShake Heater-Shaker",
  "manufacturer": "",
  "description": "一体化的加热与振荡平台，用于固定并振荡微孔板或样品托盘。设备带有可夹紧的板夹机构、温控单元（加热，可能支持主动冷却）以及可调速的振荡/加速/减速控制，常用于样品孵育、混匀和温控反应。",
  "description_en": "An integrated heater and orbital shaker platform for clamping and agitating microplates or sample trays. The device includes a plate-clamping mechanism, temperature control (heating, with possible active cooling support), and adjustable shaking speed, acceleration and deceleration—used for incubating, mixing and temperature-controlled sample processing.",
  "actions": [
    {
      "action_name": "auto-deactivate",
      "description": "停止温度控制（关闭加热/温控功能）",
      "description_en": "stop temperature control (deactivate heating/temperature regulation)"
    },
    {
      "action_name": "auto-home",
      "description": "将机械平台回到原点位置以初始化设备（回零）",
      "description_en": "move the mechanical platform to its home position to initialize the device"
    },
    {
      "action_name": "auto-lock_plate",
      "description": "夹紧并固定放置在振荡平台上的微孔板或样品板",
      "description_en": "physically clamp and secure a microplate or sample plate to the shaker platform"
    },
    {
      "action_name": "auto-reset",
      "description": "重置设备以清除错误状态并刷新通信/缓冲",
      "description_en": "reset the device to clear error states and flush communication buffers"
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置加热台的目标温度并启动温度控制（在允许范围内）",
      "description_en": "set the heating block target temperature and start temperature control (within allowed range)"
    },
    {
      "action_name": "auto-setup",
      "description": "初始化设备：执行复位并（可选）回零以准备运行",
      "description_en": "initialize the device: perform reset and optionally home to prepare for operation"
    },
    {
      "action_name": "auto-shake",
      "description": "以指定速度和加速度启动振荡以混匀样品（针对微孔板/托盘）",
      "description_en": "start shaking at the specified speed and acceleration to agitate samples (for microplates/trays)"
    },
    {
      "action_name": "auto-stop",
      "description": "立即停止当前动作（例如振荡或平台运动）",
      "description_en": "immediately stop current actions (e.g., shaking or platform movement)"
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "以指定减速度停止振荡",
      "description_en": "stop shaking, applying the specified deceleration"
    },
    {
      "action_name": "auto-unlock_plate",
      "description": "释放板夹，解除对微孔板或样品板的固定",
      "description_en": "release the plate clamp and unlock the microplate or sample plate from the platform"
    },
    {
      "action_name": "auto-supports_locking",
      "description": "get 获取设备是否支持板夹功能",
      "description_en": "get whether device supports plate locking"
    },
    {
      "action_name": "auto-supports_active_cooling",
      "description": "get 获取设备是否支持主动制冷",
      "description_en": "get whether device supports active cooling"
    },
    {
      "action_name": "auto-get_current_temperature",
      "description": "get 获取设备当前温度读数",
      "description_en": "get the device's current temperature reading"
    }
  ],
  "tag_hints": [
    "heater-shaker",
    "microplate shaking",
    "temperature control",
    "plate locking",
    "active cooling",
    "acceleration/deceleration control"
  ]
}
